// The Inkoxide document schema, for client-side validation (e.g. ajv) and,
// through index.d.ts, for typing documents. Hand-written; the types are
// generated by scripts/gen-schema-types.mjs.

import schema from './document.v1.json' with { type: 'json' };

export { schema };

export const SCHEMA_VERSION = 1;

export const enginePath = (error) => {
  let path = '';
  for (const raw of error.instancePath.split('/').slice(1)) {
    const seg = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    path += /^\d+$/.test(seg) ? `[${seg}]` : path ? `.${seg}` : seg;
  }
  const extra =
    error.keyword === 'additionalProperties'
      ? error.params?.additionalProperty
      : error.keyword === 'required'
        ? error.params?.missingProperty
        : undefined;
  if (typeof extra === 'string') path += path ? `.${extra}` : extra;
  return path;
};
